CREATE TABLE IF NOT EXISTS member_level(id BIGINT PRIMARY KEY AUTO_INCREMENT,tenant_id BIGINT NOT NULL,name VARCHAR(80) NOT NULL,threshold BIGINT NOT NULL DEFAULT 0,discount_percent INT NOT NULL DEFAULT 100,status INT NOT NULL DEFAULT 1,version BIGINT NOT NULL DEFAULT 0,UNIQUE KEY uk_member_level_tenant(tenant_id,id),CONSTRAINT fk_member_level_tenant FOREIGN KEY(tenant_id) REFERENCES tenant(id));
CREATE TABLE IF NOT EXISTS member_tag(id BIGINT PRIMARY KEY AUTO_INCREMENT,tenant_id BIGINT NOT NULL,name VARCHAR(80) NOT NULL,status INT NOT NULL DEFAULT 1,version BIGINT NOT NULL DEFAULT 0,UNIQUE KEY uk_member_tag_tenant(tenant_id,id),CONSTRAINT fk_member_tag_tenant FOREIGN KEY(tenant_id) REFERENCES tenant(id));
CREATE TABLE IF NOT EXISTS member (id BIGINT PRIMARY KEY AUTO_INCREMENT,tenant_id BIGINT NOT NULL,user_id BIGINT NULL,store_id BIGINT NOT NULL,member_no VARCHAR(50) NOT NULL,name VARCHAR(100) NOT NULL DEFAULT '',phone VARCHAR(32) NOT NULL DEFAULT '',birthday VARCHAR(10),remark VARCHAR(500),status INT NOT NULL DEFAULT 1,level_id BIGINT,version BIGINT NOT NULL DEFAULT 0,total_spent BIGINT NOT NULL DEFAULT 0,order_count BIGINT NOT NULL DEFAULT 0,create_time TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY member_user(tenant_id,user_id),UNIQUE KEY member_number(tenant_id,member_no),UNIQUE KEY member_tenant(tenant_id,id),KEY ix_member_page(tenant_id,status,level_id,create_time,id),CONSTRAINT fk_member_store FOREIGN KEY(tenant_id,store_id) REFERENCES store(tenant_id,id),CONSTRAINT fk_member_level FOREIGN KEY(tenant_id,level_id) REFERENCES member_level(tenant_id,id));
CREATE TABLE IF NOT EXISTS member_store (tenant_id BIGINT NOT NULL,member_id BIGINT NOT NULL,store_id BIGINT NOT NULL,PRIMARY KEY(tenant_id,member_id,store_id),CONSTRAINT fk_member_store_member FOREIGN KEY(tenant_id,member_id) REFERENCES member(tenant_id,id),KEY ix_member_store(tenant_id,store_id,member_id),CONSTRAINT fk_member_store_store FOREIGN KEY(tenant_id,store_id) REFERENCES store(tenant_id,id));
CREATE TABLE IF NOT EXISTS member_tag_relation(tenant_id BIGINT NOT NULL,member_id BIGINT NOT NULL,tag_id BIGINT NOT NULL,PRIMARY KEY(tenant_id,member_id,tag_id),CONSTRAINT fk_member_tag_relation_member FOREIGN KEY(tenant_id,member_id) REFERENCES member(tenant_id,id),CONSTRAINT fk_tag_rel_tag FOREIGN KEY(tenant_id,tag_id) REFERENCES member_tag(tenant_id,id));
CREATE TABLE IF NOT EXISTS member_rule(tenant_id BIGINT PRIMARY KEY,earn_per_yuan INT NOT NULL DEFAULT 1,points_per_yuan INT NOT NULL DEFAULT 100,max_deduction_percent INT NOT NULL DEFAULT 10,allow_coupon_with_points INT NOT NULL DEFAULT 1,allow_coupon_with_level INT NOT NULL DEFAULT 0,version BIGINT NOT NULL DEFAULT 0,CONSTRAINT fk_member_rule_tenant FOREIGN KEY(tenant_id) REFERENCES tenant(id));
CREATE TABLE IF NOT EXISTS member_wallet(tenant_id BIGINT NOT NULL,member_id BIGINT NOT NULL,environment VARCHAR(10) NOT NULL,level_id BIGINT,total_spent BIGINT NOT NULL DEFAULT 0,order_count BIGINT NOT NULL DEFAULT 0,points BIGINT NOT NULL DEFAULT 0,points_held BIGINT NOT NULL DEFAULT 0,points_debt BIGINT NOT NULL DEFAULT 0,principal BIGINT NOT NULL DEFAULT 0,gift BIGINT NOT NULL DEFAULT 0,principal_held BIGINT NOT NULL DEFAULT 0,gift_held BIGINT NOT NULL DEFAULT 0,PRIMARY KEY(tenant_id,member_id,environment),CONSTRAINT fk_member_wallet_member FOREIGN KEY(tenant_id,member_id) REFERENCES member(tenant_id,id));
CREATE TABLE IF NOT EXISTS member_operation_log(id BIGINT PRIMARY KEY AUTO_INCREMENT,tenant_id BIGINT NOT NULL,environment VARCHAR(10) NOT NULL,operation_key VARCHAR(150) NOT NULL,payload VARCHAR(4000) NOT NULL,result_id BIGINT,create_time TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY operation_replay(tenant_id,environment,operation_key),CONSTRAINT fk_member_operation_log_tenant FOREIGN KEY(tenant_id) REFERENCES tenant(id));
CREATE TABLE IF NOT EXISTS member_asset_ledger(id BIGINT PRIMARY KEY AUTO_INCREMENT,tenant_id BIGINT NOT NULL,member_id BIGINT NOT NULL,store_id BIGINT NOT NULL,environment VARCHAR(10) NOT NULL,asset VARCHAR(20) NOT NULL,delta BIGINT NOT NULL,before_amount BIGINT NOT NULL,after_amount BIGINT NOT NULL,business_key VARCHAR(160) NOT NULL,reason VARCHAR(500) NOT NULL,operator_id BIGINT,create_time TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY ledger_once(tenant_id,environment,business_key,asset),CONSTRAINT fk_member_asset_ledger_member FOREIGN KEY(tenant_id,member_id) REFERENCES member(tenant_id,id),KEY ix_member_asset_ledger_history(tenant_id,member_id,environment,create_time,id));
CREATE TABLE IF NOT EXISTS member_recharge_plan(id BIGINT PRIMARY KEY AUTO_INCREMENT,tenant_id BIGINT NOT NULL,name VARCHAR(100) NOT NULL,amount BIGINT NOT NULL,gift_amount BIGINT NOT NULL DEFAULT 0,status INT NOT NULL DEFAULT 1,version BIGINT NOT NULL DEFAULT 0,UNIQUE KEY uk_member_recharge_plan_tenant(tenant_id,id),CONSTRAINT fk_member_recharge_plan_tenant FOREIGN KEY(tenant_id) REFERENCES tenant(id));
CREATE TABLE IF NOT EXISTS member_recharge_order(id BIGINT PRIMARY KEY AUTO_INCREMENT,tenant_id BIGINT NOT NULL,member_id BIGINT NOT NULL,store_id BIGINT NOT NULL,environment VARCHAR(10) NOT NULL,number VARCHAR(60) NOT NULL,amount BIGINT NOT NULL,gift_amount BIGINT NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'PENDING',principal_remaining BIGINT NOT NULL DEFAULT 0,gift_remaining BIGINT NOT NULL DEFAULT 0,principal_held BIGINT NOT NULL DEFAULT 0,gift_held BIGINT NOT NULL DEFAULT 0,payment_account_id VARCHAR(100),create_time TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY recharge_number(tenant_id,number),UNIQUE KEY uk_member_recharge_order_tenant(tenant_id,id),CONSTRAINT fk_member_recharge_order_member FOREIGN KEY(tenant_id,member_id) REFERENCES member(tenant_id,id),KEY ix_member_recharge_order_history(tenant_id,member_id,environment,create_time,id));
CREATE TABLE IF NOT EXISTS coupon_template(id BIGINT PRIMARY KEY AUTO_INCREMENT,tenant_id BIGINT NOT NULL,name VARCHAR(100) NOT NULL,type VARCHAR(15) NOT NULL,`value` BIGINT NOT NULL,min_spend BIGINT NOT NULL DEFAULT 0,max_discount BIGINT,start_time TIMESTAMP NOT NULL,end_time TIMESTAMP NOT NULL,total_stock BIGINT NOT NULL,issued BIGINT NOT NULL DEFAULT 0,per_member_limit INT NOT NULL DEFAULT 1,points_cost BIGINT NOT NULL DEFAULT 0,store_ids VARCHAR(3000) NOT NULL,fulfillment_types VARCHAR(1000) NOT NULL,status INT NOT NULL DEFAULT 1,version BIGINT NOT NULL DEFAULT 0,UNIQUE KEY uk_coupon_template_tenant(tenant_id,id),CONSTRAINT fk_coupon_template_tenant FOREIGN KEY(tenant_id) REFERENCES tenant(id));
CREATE TABLE IF NOT EXISTS member_coupon(id BIGINT PRIMARY KEY AUTO_INCREMENT,tenant_id BIGINT NOT NULL,member_id BIGINT NOT NULL,environment VARCHAR(10) NOT NULL,template_id BIGINT NOT NULL,snapshot TEXT NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'AVAILABLE',order_id BIGINT,create_time TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uk_member_coupon_tenant(tenant_id,id),CONSTRAINT fk_member_coupon_member FOREIGN KEY(tenant_id,member_id) REFERENCES member(tenant_id,id),CONSTRAINT fk_coupon_template FOREIGN KEY(tenant_id,template_id) REFERENCES coupon_template(tenant_id,id),KEY ix_member_coupon_history(tenant_id,member_id,environment,create_time,id));
CREATE TABLE IF NOT EXISTS member_order_asset(order_id BIGINT PRIMARY KEY,tenant_id BIGINT NOT NULL,member_id BIGINT NOT NULL,store_id BIGINT NOT NULL,environment VARCHAR(10) NOT NULL,status VARCHAR(20) NOT NULL,points BIGINT NOT NULL,principal BIGINT NOT NULL,gift BIGINT NOT NULL,coupon_id BIGINT,eligible_goods BIGINT NOT NULL,net_spend BIGINT NOT NULL,refunded_at TIMESTAMP NULL,earned BIGINT NOT NULL DEFAULT 0,earn_rate INT NOT NULL,completed INT NOT NULL DEFAULT 0,snapshot TEXT NOT NULL,CONSTRAINT fk_member_order_asset_member FOREIGN KEY(tenant_id,member_id) REFERENCES member(tenant_id,id),UNIQUE KEY uk_order_asset_tenant(tenant_id,order_id),CONSTRAINT fk_order_asset_coupon FOREIGN KEY(tenant_id,coupon_id) REFERENCES member_coupon(tenant_id,id));
CREATE TABLE IF NOT EXISTS member_order_allocation(order_id BIGINT NOT NULL,recharge_id BIGINT NOT NULL,tenant_id BIGINT NOT NULL,principal BIGINT NOT NULL,gift BIGINT NOT NULL,PRIMARY KEY(order_id,recharge_id),CONSTRAINT fk_allocation_order FOREIGN KEY(tenant_id,order_id) REFERENCES member_order_asset(tenant_id,order_id),CONSTRAINT fk_allocation_batch FOREIGN KEY(tenant_id,recharge_id) REFERENCES member_recharge_order(tenant_id,id));
