INSERT INTO rbac_permission(tenant_id,code,name) SELECT t.id,'member:read','member:read' FROM tenant t WHERE NOT EXISTS(SELECT 1 FROM rbac_permission p WHERE p.tenant_id=t.id AND p.code='member:read');
INSERT INTO role_permission(tenant_id,role_code,permission_code) SELECT r.tenant_id,r.code,'member:read' FROM rbac_role r WHERE r.code='MERCHANT_ADMIN' AND NOT EXISTS(SELECT 1 FROM role_permission p WHERE p.tenant_id=r.tenant_id AND p.role_code=r.code AND p.permission_code='member:read');
