INSERT INTO member_level(tenant_id,name,threshold,discount_percent) SELECT t.id,d.name,d.threshold,100 FROM tenant t CROSS JOIN (SELECT '普通会员' name,0 threshold UNION ALL SELECT '银卡',50000 UNION ALL SELECT '金卡',200000) d WHERE NOT EXISTS(SELECT 1 FROM member_level l WHERE l.tenant_id=t.id);
